 static IEnumerator Walk(VenueFinale m,Vector3 at){var p=m.Player;var path=new NavMeshPath();Check(NavMesh.CalculatePath(p.transform.position,at,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete,"connected route to "+at);var cc=p.GetComponent<CharacterController>();foreach(var corner in path.corners.Skip(1)){float end=Time.time+35;while(Vector2.Distance(new(p.transform.position.x,p.transform.position.z),new(corner.x,corner.z))>.4f){if(Time.time>end)throw new Exception("blocked "+p.transform.position+" -> "+corner);var d=corner-p.transform.position;d.y=0;p.View.transform.rotation=Quaternion.LookRotation(d);cc.Move((d.normalized*6+Vector3.down*3)*Time.deltaTime);yield return null;}}}
 static void SafeEnemies(VenueFinale m){foreach(var e in m.Enemies)e.ExternalAttackControl=true;}
 public static IEnumerator Vehicle(){log="First event boarding visual check\n";yield return Wait(.5f);var m=VenueFinale.Current;var recon=m.preparation.preparation;var b=recon.delivery.broker;typeof(BrokerMission).GetProperty("State").SetValue(b,BrokerMission.Phase.Complete);typeof(SpecialOrderMission).GetProperty("State").SetValue(recon.delivery,SpecialOrderMission.Phase.Complete);typeof(BackdoorMission).GetProperty("State").SetValue(recon,BackdoorMission.Phase.Complete);typeof(MechanicMission).GetProperty("State").SetValue(m.preparation,MechanicMission.Phase.Complete);b.day.EnterNightPreparation();StoryPhoneInbox.Current.AutoOpenEnabled=false;typeof(VenueFinale).GetProperty("EventDay").SetValue(m,b.day.currentDay);Check(m.Begin(),"vehicle visual setup starts");m.SkipCinematic();typeof(VenueFinale).GetProperty("State").SetValue(m,VenueFinale.Phase.StreetEscape);typeof(VenueFinale).GetField("turned",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(m,true);m.PlacePlayer(m.carStand);yield return null;Check(m.Interact(),"board interaction works");yield return Wait(m.boardingSeconds*.5f);BrokerMissionCheck.Capture(b,"Venue-boarding",m.cinema);yield return Wait(m.boardingSeconds*.6f);Check(m.State==VenueFinale.Phase.Driving,"boarding finishes");yield return Wait(.4f);float roof=m.car.GetComponent<Renderer>().bounds.max.y;Check(m.driver.GetComponentInChildren<Animator>().GetBoneTransform(HumanBodyBones.Head).position.y<roof,"driver below roof");Check(m.passenger.GetComponentInChildren<Animator>().GetBoneTransform(HumanBodyBones.Head).position.y<roof,"passenger below roof");BrokerMissionCheck.Capture(b,"Venue-escape",m.cinema);yield return Wait(m.driveSeconds);Check(m.State==VenueFinale.Phase.Debrief,"drive reaches closing scene");m.SkipCinematic();Check(m.Completed&&!m.cinema.enabled,"visual check restores control");}
 public static IEnumerator Verify(){log="First event playable flow\n";yield return Wait(.5f);var m=VenueFinale.Current;Check(m&&m.interior&&m.car&&m.door&&m.target,"saved scene references");Check(!m.Begin(),"locked before preparation");var earlyApp=UnityEngine.Object.FindFirstObjectByType<StoryPhoneApp>(FindObjectsInactive.Include);earlyApp.Open(false);Check(earlyApp.VisibleMissionCount==1,"only first mission visible before unlock");earlyApp.Move(-1);Check(earlyApp.Selection==0,"up does not wrap to future mission");earlyApp.Move(10);Check(earlyApp.Selection==0,"locked missions cannot be browsed");earlyApp.gameObject.SetActive(false);var recon=m.preparation.preparation;var broker=recon.delivery.broker;typeof(BrokerMission).GetProperty("State").SetValue(broker,BrokerMission.Phase.Complete);typeof(SpecialOrderMission).GetProperty("State").SetValue(recon.delivery,SpecialOrderMission.Phase.Complete);typeof(BackdoorMission).GetProperty("State").SetValue(recon,BackdoorMission.Phase.Complete);Check(!m.Ready,"mechanic support required");earlyApp.Open(false);Check(earlyApp.VisibleMissionCount==4,"preparation unlocks missions in order");earlyApp.Move(3);earlyApp.Refresh();Check(earlyApp.rows[0].text.Contains("COMPLETED"),"completed missions have distinct badge");earlyApp.gameObject.SetActive(false);typeof(MechanicMission).GetProperty("State").SetValue(m.preparation,MechanicMission.Phase.Complete);broker.day.EnterNightPreparation();StoryPhoneInbox.Current.AutoOpenEnabled=false;broker.day.fadeDuration=.05f;int day=broker.day.currentDay;int money=MoneyManager.Instance.currentMoney;
 var app=UnityEngine.Object.FindFirstObjectByType<StoryPhoneApp>(FindObjectsInactive.Include);app.Open(false);app.Move(4);app.Confirm();app.Refresh();Check(app.action.text=="행사 당일로 출발","phone finale unlocked");app.Confirm();float deadline=Time.time+15;while(m.State==VenueFinale.Phase.Scheduling&&Time.time<deadline)yield return null;Check(m.State==VenueFinale.Phase.Opening&&m.EventDay==day+1&&!broker.day.isShopOpen,"event day skips shop opening");Time.timeScale=0;m.SkipCinematic();Check(m.State==VenueFinale.Phase.Opening,"paused cinematic cannot skip");Time.timeScale=1;yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==VenueFinale.Phase.Entrance&&!m.cinema.enabled&&m.Player.GetComponent<PlayerMove>().isControllable,"opening skip restores control");
 Check(StoryPhoneInbox.Current.Messages.Any(t=>t.sender=="정비사"&&!t.localConversation),"mechanic sends remote waiting text");var move=m.Player.GetComponent<PlayerMove>();move.enabled=false;var look=m.Player.View.GetComponent<CameraMove>();look.enabled=false;m.PlacePlayer(m.entry);yield return null;yield return Key(UnityEngine.InputSystem.Key.F);Check(m.State==VenueFinale.Phase.Admission&&m.approval.activeSelf,"F admits approved delivery");yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==VenueFinale.Phase.Deposit&&Vector3.Distance(m.Player.transform.position,m.inside.position)<2,"admission enters venue with control");look.enabled=false;
 m.Cancel();Check(m.State==VenueFinale.Phase.Failed&&m.Ready&&!BrokerMission.Active&&Vector3.Distance(m.Player.transform.position,m.entry.position)<2,"cancel inside restores street and keeps preparation");Check(m.Begin()&&m.State==VenueFinale.Phase.Opening&&broker.day.currentDay==day+1,"retry does not advance another day");m.SkipCinematic();move.enabled=false;look.enabled=false;m.PlacePlayer(m.entry);Check(m.Interact(),"retry entry usable");m.SkipCinematic();look.enabled=false;
 var bike=UnityEngine.Object.FindFirstObjectByType<MotorcycleController>();bike.isDriven=true;yield return null;yield return null;Check(!m.pizza.activeSelf,"mission pizza hidden on motorcycle");bike.isDriven=false;yield return null;yield return null;Check(m.pizza.activeSelf,"mission pizza returns after dismount");
 yield return Walk(m,m.deliveryTable.position+Vector3.back*2);yield return Key(UnityEngine.InputSystem.Key.F);Check(m.State==VenueFinale.Phase.Observe,"pizza physically deposited");yield return Walk(m,m.observeStand.position);m.Player.View.transform.LookAt(m.target.position+Vector3.up*1.4f);yield return null;Check(m.CanObserve(),"target visible from observation position");var speaker=m.target.GetComponent<VenueSpeakerPerformance>();Check(speaker,"speaker performance saved in scene");Quaternion speechRotation=m.target.localRotation;yield return Wait(.3f);Check(Quaternion.Angle(speechRotation,m.target.localRotation)>.01f,"speaker gestures and turns during observation");BrokerMissionCheck.Capture(broker,"Venue-observation");Time.timeScale=0;m.Observe(true,10);Check(m.ObservationProgress==0,"paused observation makes no progress");Time.timeScale=1;InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(UnityEngine.InputSystem.Key.F));yield return Wait(m.observeSeconds+.1f);InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;Check(m.State==VenueFinale.Phase.Conversation,"held F opens overheard conversation");yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==VenueFinale.Phase.Exposed&&m.IntelSecured,"evidence leads to discovery cinematic");yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.State==VenueFinale.Phase.InteriorEscape&&m.Enemies.Length==2,"escape starts with bounded first wave");DeveloperCheats.SetInvincible(true);Check(!m.ExitUnlocked,"escape blocked before combat");
 var enemy=m.Enemies[0];var animator=enemy.GetComponentInChildren<Animator>();float runDeadline=Time.time+2;while(animator.GetFloat("MoveSpeed")<.2f&&Time.time<runDeadline)yield return null;Check(animator.enabled&&animator.GetFloat("RunRate")>.1f&&animator.GetFloat("MoveSpeed")>.1f,"enemy running animator receives movement and nonzero playback rate");
 float animationTime=animator.GetCurrentAnimatorStateInfo(0).normalizedTime;yield return Wait(.2f);Check(animator.GetCurrentAnimatorStateInfo(0).normalizedTime!=animationTime,"enemy locomotion advances instead of frozen pose");
 SafeEnemies(m);enemy.ExternalAttackControl=false;
 var attackStand=new GameObject("Temporary combat check stand").transform;attackStand.position=enemy.transform.position+enemy.transform.forward*1.8f;attackStand.rotation=Quaternion.LookRotation(-enemy.transform.forward);m.PlacePlayer(attackStand);UnityEngine.Object.Destroy(attackStand.gameObject);
 float attackDeadline=Time.time+5;while(!enemy.IsPunching&&Time.time<attackDeadline)yield return null;Check(enemy.IsPunching,"mission enemy starts close-range attack");
 var hand=animator.GetBoneTransform(HumanBodyBones.RightHand);Vector3 firstHand=enemy.transform.InverseTransformPoint(hand.position);yield return Wait(.4f);Check(Vector3.Distance(firstHand,enemy.transform.InverseTransformPoint(hand.position))>.04f,"punch animation moves hand toward player");
 Check(enemy.ReceiveKick(m.Player,Vector3.right,30)&&enemy.Npc.IsKnockedDown&&!animator.enabled,"hit transfers enemy to physical ragdoll");yield return Wait(4);Check(!enemy.Npc.IsKnockedDown&&animator.enabled&&enemy.Health==70,"enemy recovers animation and resumes pursuit after hit");
 SafeEnemies(m);Check(m.SubduedCount==1&&!m.ExitUnlocked,"one guard is insufficient to clear blockade");var second=m.Enemies.First(e=>e!=enemy);Check(second.ReceiveKick(m.Player,Vector3.right,30),"second guard can be subdued");yield return null;yield return null;Check(m.ExitUnlocked,"two distinct subdued guards clear exit");m.PlacePlayer(m.observeStand);look.enabled=false;
 // 적 AI의 전투는 기존 시스템을 사용하고, 경로 검증에서는 피격을 잠시 차단한다.
 yield return Walk(m,m.inside.position);SafeEnemies(m);Check(m.Enemies.Length<=4,"reinforcement cap four");foreach(var waypoint in m.serviceRoute)yield return Walk(m,waypoint.position);yield return Key(UnityEngine.InputSystem.Key.F);DeveloperCheats.SetInvincible(false);Check(m.State==VenueFinale.Phase.StreetEscape&&m.Enemies.Length==2,"service exit returns to surveyed city route");SafeEnemies(m);look.enabled=false;foreach(var waypoint in m.alleyRoute)yield return Walk(m,waypoint.position);yield return Walk(m,m.carStand.position);yield return Key(UnityEngine.InputSystem.Key.F);Check(m.State==VenueFinale.Phase.Boarding,"F boards mechanic getaway car");Check(!m.Player.CanReceiveHit,"boarding prevents invisible cinematic damage");yield return Wait(m.boardingSeconds*.5f);Check(Quaternion.Angle(m.door.localRotation,Quaternion.identity)>20,"door visibly opens during boarding");BrokerMissionCheck.Capture(broker,"Venue-boarding",m.cinema);yield return Wait(m.boardingSeconds*.6f);Check(m.State==VenueFinale.Phase.Driving,"boarding enters vehicle escape");BrokerMissionCheck.Capture(broker,"Venue-escape",m.cinema);yield return Wait(m.driveSeconds+.2f);Check(m.State==VenueFinale.Phase.Debrief&&Vector3.Distance(m.car.position,m.driveEnd.position)<.5f,"car physically traverses authored road");yield return Key(UnityEngine.InputSystem.Key.Space);Check(m.Completed&&!m.cinema.enabled&&!BrokerMission.Active,"ending restores gameplay and completes once");Check(Vector3.Distance(m.Player.transform.position,m.safePoint.position)<2,"player returns safely to shop");Check(m.preparation.VehicleSupportUnlocked&&recon.Completed&&!m.Begin(),"preparations retained and replay reward prevented");Check(MoneyManager.Instance.currentMoney==money,"mission does not add or spend cash");app.Open(false);app.Move(4);app.Confirm();app.Refresh();Check(app.action.text.Contains("완료"),"phone records first event completion");app.gameObject.SetActive(false);move.enabled=true;look.enabled=true;
 }
}
